const crypto = require('crypto');
const item = $input.first().json.body.items ? $input.first().json.body.items[0] : $input.first().json.body;
const year = new Date().getFullYear();
const hash = crypto.createHash('sha256').update(`${item.application_id || Date.now()}-${item.applicant_email?.[0]?.value || ''}`).digest('hex').slice(0, 6).toUpperCase();
const serialCode = `TFU-${year}-${hash}`;
const issueDate = new Date().toISOString().split('T')[0];
const recipientName = item.recipient_name || item.reviewer_notes || 'TF Unions Contributor';
const roleTitle = item.target_track?.value || item.role_or_program_title || 'STEM Opportunities Researcher — TF News';
const hoursCredited = item.logged_hours || 40;
const verifyUrl = `https://verify.tfunions.com/?code=${serialCode}`;

// Simple deterministic SVG QR placeholder pointing to verifyUrl
const qrSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="#fff"/><rect x="10" y="10" width="25" height="25" fill="#070E24"/><rect x="65" y="10" width="25" height="25" fill="#070E24"/><rect x="10" y="65" width="25" height="25" fill="#070E24"/><rect x="42" y="42" width="16" height="16" fill="#002583"/></svg>`;

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"/><style>@page{size:A4 landscape;margin:0}body{width:297mm;height:210mm;margin:0;font-family:Georgia,serif;background:#070E24;color:#fff;display:flex;align-items:center;justify-content:center;-webkit-print-color-adjust:exact}.frame{width:279mm;height:192mm;border:2.5mm solid #FFB800;padding:12mm 16mm;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(135deg,#0A1538 0%,#002583 60%,#070E24 100%)}.top{display:flex;justify-content:space-between;align-items:center}.serial{font-family:monospace;color:#FFB800;font-size:11pt}.center{text-align:center}.name{font-size:32pt;color:#FFB800;font-weight:bold;margin:4mm 0;border-bottom:1px solid #FFB800;display:inline-block;padding:0 10mm 2mm}.bottom{display:flex;justify-content:space-between;align-items:flex-end;font-family:Arial,sans-serif;font-size:9pt}</style></head><body><div class="frame"><div class="top"><div><strong>TF UNIONS FOUNDATION</strong></div><div class="serial">SERIAL: ${serialCode}</div></div><div class="center"><div style="color:#FFB800;letter-spacing:3px;font-family:Arial">VOLUNTEER SERVICE CREDENTIAL</div><h1>Certificate of Distinction</h1><div class="name">${recipientName}</div><p>For verified contribution (${hoursCredited} Hours) as <strong>${roleTitle}</strong></p></div><div class="bottom"><div><strong>Mohammed Farag</strong><br/>Founder & Principal Architect</div><div style="display:flex;align-items:center;gap:8px"><div style="width:18mm;height:18mm">${qrSvg}</div><div>Verify at:<br/><strong>${verifyUrl}</strong><br/>Issued: ${issueDate}</div></div><div><strong>Mohammed Abdelghany</strong><br/>Co-Founder</div></div></div></body></html>`;

return [{
  json: {
    serialCode,
    recipientName,
    roleTitle,
    hoursCredited,
    issueDate,
    applicantEmail: item.applicant_email?.[0]?.value || item.email,
    memberId: item.member?.[0]?.id,
    html
  },
  binary: {
    index_html: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf-8'), 'index.html', 'text/html')
  }
}];
